[{"order":1,"type":"heading","text":"TurboModules and Fabric Native Component Implementation via JSI in React Native"},{"order":2,"type":"paragraph","text":"React Native's new architecture introduces two pillars for performance improvement: TurboModules and Fabric, both built on top of the JavaScript Interface (JSI). This tutorial guides you through implementing a custom Fabric Native Component and a TurboModule from scratch."},{"order":3,"type":"heading","text":"Prerequisites and Architecture Overview"},{"order":4,"type":"paragraph","text":"Before starting, ensure your React Native project has the new architecture enabled (newArchEnabled=true in gradle.properties for Android, and RCT_NEW_ARCH_ENABLED=1 for iOS). JSI allows direct synchronous communication between JavaScript and C++ without serializing through the old bridge."},{"order":5,"type":"subheading","text":"Step 1: Defining the TurboModule Spec"},{"order":6,"type":"paragraph","text":"TurboModules use Codegen to generate native interface code at build time. First, define your specification interface in TypeScript."},{"order":7,"type":"code","text":"import { TurboModule, TurboModuleRegistry } from 'react-native';

export interface Spec extends TurboModule {
  getDeviceToken(): Promise<string>;
  logEvent(eventName: string, params: Object): void;
}

export default TurboModuleRegistry.getEnforcing<Spec>('NativeLoggerModule');"},{"order":8,"type":"subheading","text":"Step 2: Configuring Codegen"},{"order":9,"type":"paragraph","text":"Update your package.json to include the codegen configuration so React Native knows which files to parse during compilation."},{"order":10,"type":"code","text":""codegenConfig": {
  "name": "NativeLoggerModuleSpec",
  "type": "modules",
  "jsSrcsDir": "./js"
}"},{"order":11,"type":"subheading","text":"Step 3: Implementing the TurboModule on Android"},{"order":12,"type":"paragraph","text":"Create the Java/Kotlin class implementing the generated native spec interface."},{"order":13,"type":"code","text":"package com.nativelogger;

import com.facebook.react.bridge.Promise;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.bridge.ReadableMap;

public class NativeLoggerModule extends NativeLoggerModuleSpec {
    public static final String NAME = "NativeLoggerModule";

    public NativeLoggerModule(ReactApplicationContext reactContext) {
        super(reactContext);
    }

    @Override
    public String getName() {
        return NAME;
    }

    @Override
    public void getDeviceToken(Promise promise) {
        promise.resolve("SAMPLE_TOKEN_123");
    }

    @Override
    public void logEvent(String eventName, ReadableMap params) {
        // Native logging implementation
    }
}"},{"order":14,"type":"heading","text":"Implementing a Fabric Native Component"},{"order":15,"type":"paragraph","text":"Fabric components render directly via the C++ shadow tree, bypassing the old UI manager queue. Define the component specification first."},{"order":16,"type":"code","text":"import type { DirectEventHandler } from 'react-native/Libraries/Types/CodegenTypes';
import type { Int32, WithDefault } from 'react-native/Libraries/Types/CodegenTypes';
import { codegenNativeComponent } from 'react-native';
import type { ViewProps } from 'react-native';

export type OnChangeEvent = Readonly<{
  value: string;
}>;

export interface NativeProps extends ViewProps {
  text?: string;
  count?: WithDefault<Int32, 0>;
  onChange?: DirectEventHandler<OnChangeEvent>;
}

export default codegenNativeComponent<NativeProps>('CustomCardView');"},{"order":17,"type":"subheading","text":"Step 4: Registering and Consuming"},{"order":18,"type":"bullet_point","text":"Register your TurboModule inside the TurboModulePackage class on Android."},{"order":19,"type":"bullet_point","text":"Implement the iOS Objective-C++ (.mm) files using the generated specs for both modules and components."},{"order":20,"type":"bullet_point","text":"Import and execute methods cleanly inside your React Native components using standard JavaScript imports."},{"order":21,"type":"paragraph","text":"By migrating your native modules and components to the new JSI-based architecture, you achieve faster startup times, synchronous method calls, and smoother UI rendering animations."}]
